gP6(){return"\u0626\u06d5\u0645 \u0646\u06d5\u0634\u062a\u06d5\u0631\u06af\u06d5\u0631\u06cc\u06cc\u06d5 \u0646\u0631\u062e\u06cc \u062f\u0627\u062f\u06d5\u0646\u0631\u06ce\u062a \u0628\u06d5"},
P7(a){return"\u0646\u0631\u062e ("+a+")"},
gP9(){return"\u0646\u0631\u062e (\u062f\u06c6\u0644\u0627\u0631)"},
gON(){return"\u062e\u0648\u0644\u06d5\u06a9\u06cc \u062e\u06d5\u0645\u06b5\u06ce\u0646\u0631\u0627\u0648"},
gOZ(){return"\u062e\u0627\u0646\u06d5\u06cc \u062a\u0627\u06cc\u0628\u06d5\u062a\u06cc \u0646\u0648\u06ce"},
gOK(){return"\u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc\u06a9\u0631\u062f\u0646\u06cc \u062e\u0627\u0646\u06d5\u06cc \u062a\u0627\u06cc\u0628\u06d5\u062a"},
gOO(){return'\u0646\u0627\u0648\u06cc \u062e\u0627\u0646\u06d5 (\u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 "\u06a9\u06d5\u0648\u0627\u0646")'},
gOP(){return"\u0647\u06d5\u06b5\u0628\u0698\u0627\u0631\u062f\u0646\u06d5\u06a9\u0627\u0646 \u0628\u06d5 \u06a9\u06c6\u0645\u0627 \u062c\u06cc\u0627\u06a9\u0631\u0627\u0648\u06d5\u062a\u06d5\u0648\u06d5 (\u0628\u06d5\u062a\u0627\u06b5\u06cc \u0628\u0647\u06ce\u06b5\u06d5\u0648\u06d5 \u0628\u06c6 \u0646\u0648\u0648\u0633\u06cc\u0646\u06cc \u0626\u0627\u0632\u0627\u062f)"},
gOQ(){return"\u067e\u06ce\u0648\u06cc\u0633\u062a\u06d5"},
gOR(){return"\u0633\u06d5\u0628\u0627\u0631\u06d5\u062a \u0628\u06d5"},
gOS(){return"\u0686\u0627\u0644\u0627\u06a9\u06cc\u06cc\u06d5\u06a9\u06d5 \u0628\u06d5 \u062a\u06d5\u0648\u0627\u0648\u06cc (\u06cc\u06d5\u06a9 \u062c\u0627\u0631 \u062f\u06cc\u0627\u0631\u06cc \u062f\u06d5\u06a9\u0631\u06ce\u062a)"},
gCG(){return"\u0628\u06c6 \u0647\u06d5\u0631 \u0633\u06d5\u0631\u062f\u0627\u0646\u06ce\u06a9 (\u0644\u06d5 \u0647\u06d5\u0631 \u0633\u06d5\u0631\u062f\u0627\u0646\u06ce\u06a9\u062f\u0627 \u062f\u06d5\u06af\u06c6\u0695\u06ce\u062a)"},
gIo(){return"\u0695\u06ce\u06a9\u062e\u0633\u062a\u0646\u06d5\u06a9\u0627\u0646"},
gHf(){return"\u0695\u06ce\u06a9\u062e\u0633\u062a\u0646\u06d5\u06a9\u0627\u0646\u06cc \u0644\u0642"},
