gHk(){return"\u06af\u06c6\u0695\u06cc\u0646\u06cc \u0626\u06cc\u0645\u06d5\u06cc\u0644"},
gHl(){return"\u06af\u06c6\u0695\u06cc\u0646\u06cc \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc"},
gHw(){return"\u06af\u06c6\u0695\u06cc\u0646\u06cc \u0626\u06cc\u0645\u06d5\u06cc\u0644\u06d5\u06a9\u06d5\u062a \u0644\u06d5\u0648\u0627\u0646\u06d5\u06cc\u06d5 \u067e\u06ce\u0648\u06cc\u0633\u062a\u06cc \u0628\u06d5 \u067e\u0634\u062a\u0695\u0627\u0633\u062a\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc \u0628\u06d5\u0633\u062a\u06d5\u0631\u06ce\u06a9 \u0628\u06ce\u062a \u06a9\u06d5 \u062f\u06d5\u0646\u06ce\u0631\u062f\u0631\u06ce\u062a \u0628\u06c6 \u0646\u0627\u0648\u0646\u06cc\u0634\u0627\u0646\u06cc \u0646\u0648\u06ce\u060c \u067e\u06ce\u0634 \u0626\u06d5\u0648\u06d5\u06cc \u06a9\u0627\u0631\u06cc\u06af\u06d5\u0631\u06cc \u0647\u06d5\u0628\u06ce\u062a."},
